package app.marketlens;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.time.format.*;
import java.util.*;
import java.util.regex.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.json.*;

final class Parse {
 static double number(Object o){if(o==null||o==JSONObject.NULL)return Double.NaN;try{String s=o.toString().replace(",","").trim();if(s.endsWith("%"))s=s.substring(0,s.length()-1).trim();double n=Double.parseDouble(s);return Double.isFinite(n)?n:Double.NaN;}catch(Exception e){return Double.NaN;}}
 static String str(JSONObject o,String k){if(o==null||o.isNull(k))return "";return o.optString(k,"").trim();}
 static String canonical(String s){try{return LocalDate.parse(s.trim()).toString();}catch(Exception ignored){}try{return LocalDate.parse(s.trim(),new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern("dd-MMM-uuuu").toFormatter(Locale.ENGLISH).withResolverStyle(ResolverStyle.STRICT)).toString();}catch(Exception ignored){}return "";}
 static String header(String s){return s.replace("\uFEFF","").toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","");}
 static List<List<String>> csv(String text)throws IOException{List<List<String>> rows=new ArrayList<>();List<String> row=new ArrayList<>();StringBuilder cell=new StringBuilder();boolean quoted=false;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(c=='"'){if(quoted&&i+1<text.length()&&text.charAt(i+1)=='"'){cell.append('"');i++;}else quoted=!quoted;}else if(!quoted&&(c==','||c=='\n'||c=='\r')){row.add(cell.toString().trim());cell.setLength(0);if(c!=','){if(c=='\r'&&i+1<text.length()&&text.charAt(i+1)=='\n')i++;if(row.size()>1||!row.get(0).isEmpty())rows.add(row);row=new ArrayList<>();}}else cell.append(c);if(row.size()>200||rows.size()>100000||cell.length()>100000)throw new IOException("CSV is too large");}if(quoted)throw new IOException("CSV has an unclosed quoted field");if(cell.length()>0||!row.isEmpty()){row.add(cell.toString().trim());rows.add(row);}return rows;}
 static Map<String,Integer> headers(List<String> row){Map<String,Integer> m=new HashMap<>();for(int i=0;i<row.size();i++)m.put(header(row.get(i)),i);return m;}
 static String col(List<String> r,Map<String,Integer> h,String key){Integer i=h.get(key);return i!=null&&i<r.size()?r.get(i):"";}
 static List<Data.Stock> catalog(String raw)throws Exception{List<List<String>> rows=csv(raw);if(rows.size()<2)throw new IOException("Stock directory is empty");Map<String,Integer> h=headers(rows.get(0));if(!h.containsKey("symbol")||!h.containsKey("isinnumber"))throw new IOException("Unrecognized NSE stock directory");List<Data.Stock> out=new ArrayList<>();for(int i=1;i<rows.size();i++){List<String> r=rows.get(i);String s=Data.symbol(col(r,h,"symbol")),isin=col(r,h,"isinnumber");if(Data.validSymbol(s)&&Data.isin(isin)){Data.Stock stock=new Data.Stock(s,col(r,h,"nameofcompany"),isin);stock.series=col(r,h,"series");out.add(stock);}}return out;}
 static Data.Screen screen(String raw)throws Exception{JSONObject j=new JSONObject(raw);if(!j.has("dataLtpGreater20")||!j.has("dataLtpLess20")||str(j,"timestamp").isEmpty())throw new IOException("Unrecognized high/low response");Data.Screen out=new Data.Screen();out.stamp=str(j,"timestamp");Map<String,Data.Hit> unique=new LinkedHashMap<>();for(String key:new String[]{"dataLtpGreater20","dataLtpLess20"}){JSONArray a=j.optJSONArray(key);if(a==null)throw new IOException("Invalid high/low list");for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String symbol=Data.symbol(str(o,"symbol"));if(!Data.validSymbol(symbol))continue;Data.Hit h=new Data.Hit();h.stock=new Data.Stock(symbol,str(o,"comapnyName"),"");h.last=number(o.opt("ltp"));h.level=number(o.opt("new52WHL"));h.change=number(o.opt("pChange"));unique.put(symbol,h);}}out.hits.addAll(unique.values());return out;}
 static Data.Quote quote(String raw,String wanted)throws Exception{return quote(raw,wanted,"EQ");}
 static Data.Quote quote(String raw,String wanted,String series)throws Exception{JSONObject root=new JSONObject(raw);JSONArray a=root.optJSONArray("equityResponse");if(a==null||a.length()==0)throw new IOException("No equity quote returned");JSONObject o=null;for(int i=0;i<a.length();i++){JSONObject candidate=a.getJSONObject(i),m=candidate.optJSONObject("metaData");if(wanted.equalsIgnoreCase(str(m,"symbol"))&&series.equals(str(m,"series"))){o=candidate;break;}}if(o==null)throw new IOException("Quote did not match the selected stock series");JSONObject meta=o.optJSONObject("metaData"),trade=o.optJSONObject("tradeInfo"),price=o.optJSONObject("priceInfo"),sec=o.optJSONObject("secInfo");if(meta==null||trade==null||price==null)throw new IOException("Quote fields are missing");Data.Quote q=new Data.Quote();q.stamp=str(o,"lastUpdateTime");q.isin=str(meta,"isinCode");q.series=str(meta,"series");q.industry=str(sec,"basicIndustry");q.last=number(trade.opt("lastPrice"));q.change=number(meta.opt("pChange"));q.low=number(price.opt("yearLow"));q.high=number(price.opt("yearHigh"));q.lowDate=str(price,"yearLowDt");q.highDate=str(price,"yearHightDt");q.pe=sec==null?Double.NaN:number(sec.opt("pdSymbolPe"));q.cap=number(trade.opt("totalMarketCap"));q.face=number(trade.opt("faceValue"));if(q.stamp.isEmpty()||!Double.isFinite(q.last))throw new IOException("Quote lacks a price or source time");return q;}
 static JSONObject latest(String raw,String symbol,boolean financial)throws Exception{Object parsed=new JSONTokener(raw).nextValue();JSONArray a=parsed instanceof JSONArray?(JSONArray)parsed:parsed instanceof JSONObject?((JSONObject)parsed).optJSONArray("data"):null;if(a==null)throw new IOException("Unrecognized filing list");JSONObject best=null;String bestDate="";for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null||!symbol.equalsIgnoreCase(str(o,"symbol")))continue;String date=canonical(str(o,financial?"qe_Date":"date"));String url=str(o,"xbrl");if(date.isEmpty()||!Net.allowed(url)||!url.contains("/xbrl/")||url.endsWith("/-"))continue;boolean better=best==null||date.compareTo(bestDate)>0;if(date.equals(bestDate)){boolean c="Consolidated".equalsIgnoreCase(str(o,"consolidated")),bc="Consolidated".equalsIgnoreCase(str(best,"consolidated"));if(financial&&c!=bc)better=c;else better=broadcast(o,financial)>broadcast(best,financial);}if(better){best=o;bestDate=date;}}if(best==null)throw new IOException("No matching "+(financial?"integrated financial":"shareholding")+" filing found");return best;}
 static long broadcast(JSONObject j,boolean financial){String s=str(j,financial?"broadcast_Date":"broadcastDate");try{return LocalDateTime.parse(s,new DateTimeFormatterBuilder().parseCaseInsensitive().appendPattern("dd-MMM-uuuu HH:mm:ss").toFormatter(Locale.ENGLISH)).toEpochSecond(ZoneOffset.UTC);}catch(Exception e){return 0;}}
 static Document xml(byte[] raw)throws Exception{if(raw.length>4*1024*1024)throw new IOException("XML part exceeds safe size");String text=new String(raw,StandardCharsets.UTF_8);if(text.toUpperCase(Locale.ROOT).contains("<!DOCTYPE")||text.toUpperCase(Locale.ROOT).contains("<!ENTITY"))throw new IOException("XML document types and entities are not allowed");DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setValidating(false);for(String flag:new String[]{"http://xml.org/sax/features/external-general-entities","http://xml.org/sax/features/external-parameter-entities","http://apache.org/xml/features/nonvalidating/load-external-dtd"})try{f.setFeature(flag,false);}catch(Exception ignored){}DocumentBuilder b=f.newDocumentBuilder();b.setEntityResolver((publicId,systemId)->new org.xml.sax.InputSource(new StringReader("")));return b.parse(new ByteArrayInputStream(raw));}
 static String name(Node n){return n.getLocalName()!=null?n.getLocalName():n.getNodeName().replaceFirst("^.*:","");}
 static List<Element> elements(Node node,String local){List<Element> found=new ArrayList<>();NodeList children=node instanceof Document?((Document)node).getElementsByTagNameNS("*",local):((Element)node).getElementsByTagNameNS("*",local);for(int i=0;i<children.getLength();i++)found.add((Element)children.item(i));return found;}
 static String first(Node n,String local){List<Element> a=elements(n,local);return a.isEmpty()?"":a.get(0).getTextContent().trim();}
 static String group(Element context){List<Element> typed=elements(context,"typedMember");if(!typed.isEmpty())return typed.get(0).getTextContent().trim();return context.getAttribute("id");}
 static Map<String,Element> contexts(Document d){Map<String,Element> out=new LinkedHashMap<>();for(Element e:elements(d,"context"))out.put(e.getAttribute("id"),e);return out;}
 static Map<String,Map<String,String>> facts(Document doc,Map<String,Element> contexts){Map<String,Map<String,String>> out=new HashMap<>();NodeList all=doc.getElementsByTagName("*");for(int i=0;i<all.getLength();i++){Element e=(Element)all.item(i);String ref=e.getAttribute("contextRef");if(ref.isEmpty())continue;Element context=contexts.get(ref);String key=context==null?ref:group(context);Map<String,String> f=out.get(key);if(f==null){f=new HashMap<>();out.put(key,f);}f.put(name(e),e.getTextContent().trim());}return out;}
 static double fact(Map<String,String> f,String... keys){for(String key:keys){double d=number(f.get(key));if(Double.isFinite(d))return d;}return Double.NaN;}
 static boolean financialUnit(Document doc,String ref,String fact){for(Element unit:elements(doc,"unit"))if(ref.equals(unit.getAttribute("id"))){String measure=unit.getTextContent();return "DebtEquityRatio".equals(fact)?measure.contains("pure"):measure.contains(":INR");}return false;}
 static Data.Financial financial(byte[] raw,JSONObject filing)throws Exception{Document doc=xml(raw);Map<String,Element> contexts=contexts(doc);String end=canonical(str(filing,"qe_Date")),chosen="";long shortest=Long.MAX_VALUE;int bestDims=Integer.MAX_VALUE;for(Map.Entry<String,Element> entry:contexts.entrySet()){Element ctx=entry.getValue();String finish=first(ctx,"endDate"),start=first(ctx,"startDate");if(!end.equals(finish)||start.isEmpty())continue;long length;try{length=java.time.temporal.ChronoUnit.DAYS.between(LocalDate.parse(start),LocalDate.parse(finish));}catch(Exception e){continue;}int dims=elements(ctx,"explicitMember").size()+elements(ctx,"typedMember").size();if(length>=50&&length<=370&&(dims<bestDims||dims==bestDims&&length<shortest)){chosen=entry.getKey();shortest=length;bestDims=dims;}}if(chosen.isEmpty())throw new IOException("No comparable reporting period in this filing");Map<String,String> values=new HashMap<>();NodeList all=doc.getElementsByTagName("*");for(int i=0;i<all.getLength();i++){Element e=(Element)all.item(i);if(chosen.equals(e.getAttribute("contextRef"))){String unit=e.getAttribute("unitRef");if(!unit.isEmpty()&&financialUnit(doc,unit,name(e)))values.put(name(e),e.getTextContent().trim());}}Data.Financial f=new Data.Financial();f.end=end;f.start=first(contexts.get(chosen),"startDate");f.basis=str(filing,"consolidated");f.source=str(filing,"xbrl");f.revenue=fact(values,"RevenueFromOperations","RevenueFromOperationsNet");if(!Double.isFinite(f.revenue)){f.revenue=fact(values,"Income","TotalIncome");f.revenueLabel="Total income";}f.profit=fact(values,"ProfitLossForPeriod","ProfitLossForThePeriod","ProfitLossFromOrdinaryActivitiesAfterTax","ProfitLoss");f.eps=fact(values,"BasicEarningsLossPerShareFromContinuingAndDiscontinuedOperations","BasicEarningsLossPerShareFromContinuingOperations","BasicEarningsLossPerShare","BasicEarningsPerShareAfterExtraordinaryItems","BasicEarningsPerShareBeforeExtraordinaryItems");f.debtEquity=fact(values,"DebtEquityRatio");if(!Double.isFinite(f.revenue)&&!Double.isFinite(f.profit)&&!Double.isFinite(f.eps))throw new IOException("This filing uses a different financial taxonomy; open the original");return f;}
 static Data.Ownership ownership(byte[] raw,JSONObject filing)throws Exception{Document doc=xml(raw);Map<String,Element> contexts=contexts(doc);Map<String,Map<String,String>> all=facts(doc,contexts);Set<String> mf=new LinkedHashSet<>();for(Element c:contexts.values()){boolean member=false;for(Element e:elements(c,"explicitMember"))if(e.getTextContent().contains("MutualFundsOrUTI"))member=true;for(Element e:elements(c,"typedMember"))if(e.getAttribute("dimension").contains("MutualFundsOrUTI"))member=true;if(member)mf.add(group(c));}Data.Ownership out=new Data.Ownership();out.date=canonical(str(filing,"date"));out.source=str(filing,"xbrl");out.promoter=number(filing.opt("pr_and_prgrp"));out.publicPct=number(filing.opt("public_val"));for(String key:mf){Map<String,String> f=all.get(key);if(f==null)continue;String name=f.get("NameOfTheShareholder");if(name==null||name.trim().isEmpty()){double v=fact(f,"ShareholdingAsAPercentageOfTotalNumberOfShares");if(Double.isFinite(v)){out.mutual=v*100;out.fundCount=fact(f,"NumberOfShareholders");}}else{Data.Holder h=new Data.Holder();h.name=name;h.shares=fact(f,"NumberOfShares","NumberOfFullyPaidUpEquityShares");double percent=fact(f,"ShareholdingAsAPercentageOfTotalNumberOfShares");h.percent=Double.isFinite(percent)?percent*100:Double.NaN;out.holders.add(h);}}ownershipExtra(doc,contexts,all,out);return out;}
 static void ownershipExtra(Document doc,Map<String,Element> contexts,Map<String,Map<String,String>> all,Data.Ownership out){
  Map<String,Double> foreign=new LinkedHashMap<>();
  for(Element c:contexts.values()){
   if(!elements(c,"typedMember").isEmpty()||!out.date.equals(first(c,"instant")))continue;
   Map<String,String> f=all.get(group(c));if(f==null)continue;
   for(Element member:elements(c,"explicitMember")){
    String category=member.getTextContent().trim();
    if(category.contains("ForeignPortfolioInvestor")||category.contains("ForeignInstitutionalInvestor")){double pct=fact(f,"ShareholdingAsAPercentageOfTotalNumberOfShares");if(Double.isFinite(pct))foreign.put(category,pct*100);}
    if(category.contains("ShareholdingOfPromoterAndPromoterGroup")){double shares=fact(f,"NumberOfSharesPledgedOrOtherwiseEncumbered"),total=fact(f,"NumberOfShares","NumberOfFullyPaidUpEquityShares");if(Double.isFinite(shares)&&total>0)out.pledged=shares/total*100;}
   }
  }
  if(!foreign.isEmpty()){out.foreign=0;boolean broad=false;for(Map.Entry<String,Double> e:foreign.entrySet())if(e.getKey().endsWith(":ForeignPortfolioInvestorsMember")){out.foreign=e.getValue();broad=true;break;}if(!broad){boolean fpi=foreign.keySet().stream().anyMatch(k->k.contains("ForeignPortfolioInvestor"));for(Map.Entry<String,Double> e:foreign.entrySet())if(!fpi||e.getKey().contains("ForeignPortfolioInvestor"))out.foreign+=e.getValue();}}
  if(!Double.isFinite(out.pledged))for(Element e:elements(doc,"WhetherAnySharesHeldByPromotersAreEncumberedUnderPledgedForPromoterAndPromoterGroup"))if("false".equalsIgnoreCase(e.getTextContent().trim())){Element context=contexts.get(e.getAttribute("contextRef"));if(context!=null&&(out.date.equals(first(context,"instant"))||out.date.equals(first(context,"endDate"))))out.pledged=0;}
 }
 static List<Data.Portfolio> importCsv(String raw,String fallbackFund,String date,String source)throws Exception{List<List<String>> rows=csv(raw);if(rows.size()<2)throw new IOException("CSV contains no holdings");Map<String,Integer> h=headers(rows.get(0));if(!h.containsKey("isin")||!h.containsKey("weightpercent"))throw new IOException("CSV needs isin and weight_percent columns; see the template");Map<String,Data.Portfolio> funds=new LinkedHashMap<>();for(int i=1;i<rows.size();i++){List<String> row=rows.get(i);String isin=Data.symbol(col(row,h,"isin"));if(!Data.isin(isin))throw new IOException("Invalid ISIN on row "+(i+1));String fund=col(row,h,"fund");if(fund.isEmpty())fund=fallbackFund;String asOf=col(row,h,"asof");if(asOf.isEmpty())asOf=date;asOf=canonical(asOf);if(fund.trim().isEmpty()||asOf.isEmpty())throw new IOException("Fund and reporting date are required on row "+(i+1));Data.Portfolio p=funds.get(fund);if(p==null){p=new Data.Portfolio();p.name=fund;p.id="import:"+fund.toLowerCase(Locale.ROOT);p.date=asOf;p.source=source;p.imported=true;p.fetched=System.currentTimeMillis();funds.put(fund,p);}if(!p.date.equals(asOf))throw new IOException("One snapshot per fund and reporting date is required");Data.Holding item=new Data.Holding();item.fund=fund;item.asOf=asOf;item.isin=isin;item.stock=col(row,h,"stockname");item.industry=col(row,h,"industry");item.weight=number(col(row,h,"weightpercent"));item.shares=number(col(row,h,"quantity"));item.source=source;if(!Double.isFinite(item.weight)||item.weight<0||item.weight>100||Double.isFinite(item.shares)&&item.shares<0)throw new IOException("Invalid weight or quantity on row "+(i+1));for(Data.Holding old:p.holdings)if(old.isin.equals(item.isin))throw new IOException("Repeated stock ISIN in one CSV fund snapshot");p.holdings.add(item);}return new ArrayList<>(funds.values());}
}
